15	// 首页容量准确性端到端回归：
16	//
17	// 服务端的精确整数校验已由 HTTP 层测试覆盖；这里补上“用户在首页表单填写
18	// → 浏览器提交 → 服务端保存 → 首页列表显示”这一段的保障。测试启动真实
19	// HTTP 服务（httptest）与本机无头 Chrome，由 testdata/homepage_browser_test.mjs
20	// 通过 Chrome DevTools Protocol 驱动真实首页，逐字节检查请求/响应中的
21	// capacity，并验证列表显示与失败时的表单保留行为。
22	//
23	// 脚本不依赖任何 npm 包（Node ≥22 的全局 WebSocket 即可），在缺少 node 或
24	// Chrome 的环境中跳过，保证其余测试照常运行。可用 CHROME_BIN 指定浏览器。
25	
26	type browserCheckResult struct {
27		HarnessError string `json:"harnessError"`
28		Browser      string `json:"browser"`
29		Checks       []struct {
30			Scenario string `json:"scenario"`
31			Name     string `json:"name"`
32			Pass     bool   `json:"pass"`
33			Detail   string `json:"detail"`
34		} `json:"checks"`
35	}
