1	// 首页容量准确性端到端回归脚本（由 main_test.go 通过 go test 调用，不单独运行）。
2	//
3	// 用法：node homepage_browser_test.mjs <baseURL> [chrome 可执行文件路径]
4	//
5	// 脚本用 Chrome DevTools Protocol 驱动本机无头 Chrome 打开真实首页，覆盖
6	// “用户填表 → 提交 → 查看已保存场地”的完整链路；stdout 最后一行输出 JSON
7	// 结果。除浏览器/脚本自身的基础设施故障（退出码非 0）外，页面行为层面的
8	// 断言失败都记录在 JSON 的 checks 中，由 Go 测试统一判定。
9	//
10	// 设计要点：
11	//   - 直接启动系统 Chrome 并以裸 WebSocket（Node 24 全局 WebSocket）连接
12	//     CDP，不依赖任何 npm 包，适配无外网/无 node_modules 的环境。
13	//   - 监听 Network 事件，保存发往 /api/venues 的请求体原文与响应体原文，
14	//     因此可以逐字节验证 capacity 是否仍是未加引号的十进制整数。
15	//   - 表单取值通过原型 value setter + input/change 事件注入，真实触发
16	//     页面已有的提交逻辑，而不是直接调用内部函数。
17	
18	import { spawn } from "node:child_process";
19	import fs from "node:fs";
20	import net from "node:net";
21	import os from "node:os";
22	import path from "node:path";
23	
24	const baseURL = process.argv[2];
25	const chromeArg = process.argv[3] || "";
26	if (!baseURL) {
27	  console.error("usage: node homepage_browser_test.mjs <baseURL> [chrome]");
28	  process.exit(2);
29	}
30	
31	function failInfra(message) {
32	  process.stdout.write(JSON.stringify({ harnessError: String(message) }) + "\n");
33	  process.exit(1);
34	}
35	
36	process.on("unhandledRejection", (err) => failInfra(err && err.stack || err));
37	
38	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
39	
40	function findChrome() {
41	  if (chromeArg) return chromeArg;
42	  if (process.env.CHROME_BIN) return process.env.CHROME_BIN;
43	  const candidates = [
44	    "/usr/bin/google-chrome",
45	    "/usr/bin/google-chrome-stable",
46	    "/usr/bin/chromium",
47	    "/usr/bin/chromium-browser",
48	    "/usr/local/bin/google-chrome",
49	  ];
50	  for (const c of candidates) {
51	    try {
52	      fs.accessSync(c, fs.constants.X_OK);
53	      return c;
54	    } catch { /* keep looking */ }
55	  }
56	  return "google-chrome";
57	}
58	
59	function freePort() {
60	  return new Promise((resolve, reject) => {
61	    const srv = net.createServer();
62	    srv.listen(0, "127.0.0.1", () => {
63	      const p = srv.address().port;
64	      srv.close(() => resolve(p));
65	    });
66	    srv.on("error", reject);
67	  });
68	}
69	
70	async function launchChrome() {
71	  const binary = findChrome();
72	  const port = await freePort();
73	  const profile = fs.mkdtempSync(path.join(os.tmpdir(), "tb-chrome-"));
74	  const args = [
75	    "--headless=new",
76	    "--no-sandbox",
77	    "--disable-gpu",
78	    "--disable-dev-shm-usage",
79	    "--no-first-run",
80	    "--no-default-browser-check",
81	    "--disable-background-networking",
82	    "--disable-crash-reporter",
83	    `--remote-debugging-port=${port}`,
84	    `--user-data-dir=${profile}`,
85	    "about:blank",
86	  ];
87	  const chrome = spawn(binary, args, {
88	    stdio: ["ignore", "ignore", "pipe"],
89	    detached: true,
90	  });
91	  let stderr = "";
92	  chrome.stderr.on("data", (d) => { stderr += d; });
93	
94	  let info = null;
95	  for (let i = 0; i < 60; i++) {
96	    await sleep(100);
97	    try {
98	      const res = await fetch(`http://127.0.0.1:${port}/json/version`);
99	      if (res.ok) { info = await res.json(); break; }
100	    } catch { /* not ready */ }
101	  }
102	  if (!info) {
103	    try { process.kill(-chrome.pid, "SIGKILL"); } catch { /* ignore */ }
104	    failInfra(`Chrome 未在预期时间内开启 CDP（${binary}）：${stderr.slice(-400)}`);
105	  }
106	  const cleanup = () => {
107	    try { process.kill(-chrome.pid, "SIGKILL"); } catch { /* already gone */ }
108	    try { fs.rmSync(profile, { recursive: true, force: true }); } catch { /* ignore */ }
109	  };
110	  return { port, browserInfo: info, cleanup };
111	}
112	
113	// ---- 极简 CDP 客户端 ----
114	
115	class CDP {
116	  constructor(wsUrl) {
117	    this.ws = new WebSocket(wsUrl);
118	    this.nextId = 0;
119	    this.pending = new Map();
120	    this.eventListeners = [];
121	  }
122	  async connect() {
123	    await new Promise((resolve, reject) => {
124	      this.ws.addEventListener("open", resolve, { once: true });
125	      this.ws.addEventListener("error", reject, { once: true });
126	    });
127	    this.ws.addEventListener("message", (ev) => {
128	      const msg = JSON.parse(ev.data);
129	      if (msg.id && this.pending.has(msg.id)) {
130	        const { resolve, reject } = this.pending.get(msg.id);
131	        this.pending.delete(msg.id);
132	        if (msg.error) reject(new Error(`${msg.error.message || JSON.stringify(msg.error)}`));
133	        else resolve(msg.result);
134	        return;
135	      }
136	      if (msg.method) {
137	        for (const fn of this.eventListeners) {
138	          try { fn(msg.method, msg.params); } catch { /* listener errors must not break the run */ }
139	        }
140	      }
141	    });
142	  }
143	  on(fn) { this.eventListeners.push(fn); }
144	  send(method, params = {}) {
145	    const id = ++this.nextId;
146	    return new Promise((resolve, reject) => {
147	      this.pending.set(id, { resolve, reject });
148	      this.ws.send(JSON.stringify({ id, method, params }));
149	    });
150	  }
151	  close() { try { this.ws.close(); } catch { /* ignore */ } }
152	
153	  // 在页面里求值；表达式必须是返回可 JSON 序列化值的同步表达式。
154	  async eval(expression) {
155	    const res = await this.send("Runtime.evaluate", {
156	      expression,
157	      returnByValue: true,
158	      awaitPromise: true,
159	    });
160	    if (res.exceptionDetails) {
161	      const exc = res.exceptionDetails.exception;
162	      throw new Error(`page exception: ${(exc && exc.description) || JSON.stringify(res.exceptionDetails)}`);
163	    }
164	    return res.result ? res.result.value : undefined;
165	  }
166	  async evalFn(fnSource, arg) {
167	    return this.eval(`(${fnSource})(${JSON.stringify(arg === undefined ? null : arg)})`);
168	  }
169	}
170	
171	// ---- 网络记录 ----
172	
173	function createNetworkLog(cdp) {
174	  // requests: requestId -> {method,url,postData,status,mimeType}
175	  const requests = new Map();
176	  cdp.on((method, params) => {
177	    if (method === "Network.requestWillBeSent") {
178	      const r = params.request;
179	      const rec = requests.get(params.requestId) || {};
180	      rec.method = r.method;
181	      rec.url = r.url;
182	      if (typeof r.postData === "string") rec.postData = r.postData;
183	      requests.set(params.requestId, rec);
184	    } else if (method === "Network.responseReceived") {
185	      const rec = requests.get(params.requestId) || {};
186	      rec.method = rec.method || params.request.method;
187	      rec.url = rec.url || params.request.url;
188	      rec.status = params.response.status;
189	      rec.mimeType = params.response.mimeType;
190	      requests.set(params.requestId, rec);
191	    }
192	  });
193	  const snapshot = () => Array.from(requests.values());
194	  return {
195	    snapshot,
196	    venuePosts(after = 0) {
197	      return snapshot()
198	        .filter((r) => r.method === "POST" && r.url.includes("/api/venues"))
199	        .slice(after);
200	    },
201	    venueGets() {
202	      return snapshot().filter((r) => r.method === "GET" && r.url.includes("/api/venues"));
203	    },
204	    async postDataOf(rec) {
205	      if (rec.postData !== undefined) return rec.postData;
206	      // requestWillBeSent 未携带 body 时按 requestId 补取。
207	      for (const [id, r] of requests) {
208	        if (r === rec) {
209	          try {
210	            const out = await cdp.send("Network.getRequestPostData", { requestId: id });
211	            return out.postData;
212	          } catch { return null; }
213	        }
214	      }
215	      return null;
216	    },
217	    async bodyOf(rec) {
218	      for (const [id, r] of requests) {
219	        if (r === rec) {
220	          const out = await cdp.send("Network.getResponseBody", { requestId: id });
221	          return out.base64Encoded ? Buffer.from(out.body, "base64").toString("utf8") : out.body;
222	        }
223	      }
224	      return null;
225	    },
226	  };
227	}
228	
229	// ---- 注入页面的测试驱动 ----
230	
231	// fill：按真实用户方式给字段赋 value（原型 setter + input/change），
232	// 并按需要点击“添加开放时段”生成行。字段值全部来自参数 JSON，不经任何
233	// Number 转换。
234	const PAGE_FILL = `function (data) {
235	  function setValue(el, value) {
236	    var proto = el.tagName === "SELECT" ? HTMLSelectElement.prototype : HTMLInputElement.prototype;
237	    var setter = Object.getOwnPropertyDescriptor(proto, "value").set;
238	    setter.call(el, String(value));
239	    el.dispatchEvent(new Event("input", { bubbles: true }));
240	    el.dispatchEvent(new Event("change", { bubbles: true }));
241	  }
