    try { serverMsg = JSON.parse(errBody).error || ""; } catch { /* ignore */ }
    check(S, "失败原因为时段重叠/相交",
      serverMsg.indexOf("重叠") >= 0 || serverMsg.indexOf("相交") >= 0, errBody);

