        after.form.timezone === "Asia/Tokyo" &&
        h.length === 2 &&
        h[0].weekday === "7" && h[0].start === "22:00" && h[0].end === "02:00" &&
        h[1].weekday === "1" && h[1].start === "05:00" && h[1].end === "03:00",
      JSON.stringify(after.form));
  } catch (e) {
    bad(S, "场景执行中断: " + e.message, e.stack);
  }
}

