// installFetchGate：包住 window.fetch，不改变请求的发送与服务端处理，只把
// POST /api/venues 的 Response 交还给页面业务代码的时机延后到测试放行——
// 由此确定性地造出“点击保存后、服务端结果尚未返回”的窗口：请求已真实发出
// （Network 记录里能看到请求体与状态码），而页面的成功/失败回调尚未执行。
// GET（如成功后的列表刷新）不拦截，避免卡住既有加载流程；放行后所有被挂
// 起的响应按原顺序交还。全局 __venueTestGate 提供 hold/release/pending。
const PAGE_INSTALL_FETCH_GATE = `function () {
  if (window.__venueTestGateInstalled) return true;
  window.__venueTestGateInstalled = true;
  var realFetch = window.fetch.bind(window);
  var held = [];
  var holding = false;
  window.__venueTestGate = {
    hold: function () { holding = true; return held.length; },
    release: function () {
      var n = held.length;
      var old = held;
      held = [];
      holding = false;
      old.forEach(function (go) { go(); });
      return n;
    },
    pending: function () { return held.length; }
  };
  window.fetch = function (input, init) {
    var url = typeof input === "string" ? input : ((input && input.url) || "");
    var isVenuePost = url.indexOf("/api/venues") >= 0 &&
      init && init.method && String(init.method).toUpperCase() === "POST";
    if (!isVenuePost) return realFetch(input, init);
    return realFetch(input, init).then(function (response) {
      if (!holding) return response;
      return new Promise(function (resolve) {
        held.push(function () { resolve(response); });
      });
    });
  };
  return true;
}`;

